window.TOPICS=[{"id": "t1", "slug": "maqsad-e-takhleeq", "title": "The Purpose of Creating Jinn and Mankind", "num": "1"}, {"id": "t2", "slug": "kalima-tawheed", "title": "The Meaning of the Kalimah of Tawhid", "num": "2"}, {"id": "t3", "slug": "iman-billah", "title": "Belief in Allah (Iman billah)", "num": "3"}, {"id": "t4", "slug": "taqdeer", "title": "Belief in Divine Decree (Taqdir)", "num": "4"}, {"id": "t5", "slug": "ihsan", "title": "Ihsan (Excellence)", "num": "5"}];
window.REF={"H:bukhari:13": {"l": "Sahih al-Bukhari, Hadith 13", "u": "https://sunnah.com/bukhari:13", "t": "Love for your brother what you love for yourself", "k": "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ", "a": "ihsan.html#h-bukhari-13"}, "Q:14:10": {"l": "Surah Ibrahim, 14:10", "u": "https://quran.com/14/10", "ar": "۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّۭ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌۭ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍۢ مُّبِينٍۢ ﴿١٠﴾", "tr": "Their messengers said, \"Can there be doubt about Allah, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays your death for a specified term.\" They said, \"You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority.\" (10)", "a": "iman-billah.html#q-14-10"}, "Q:43:26-27": {"l": "Surah Az-Zukhruf, 43:26-27", "u": "https://quran.com/43/26-27", "ar": "وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ ﴿٢٦﴾ إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ ﴿٢٧﴾", "tr": "And [mention, O Muhammad], when Abraham said to his father and his people, \"Indeed, I am disassociated from that which you worship (26) Except for He who created me; and indeed, He will guide me.\" (27)", "a": "kalima-tawheed.html#q-43-26-28"}, "Q:23:115": {"l": "Surah Al-Muminoon, 23:115", "u": "https://quran.com/23/115", "ar": "أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ﴿١١٥﴾", "tr": "Then did you think that We created you uselessly and that to Us you would not be returned?\" (115)", "a": "maqsad-e-takhleeq.html#q-23-115-116"}, "Q:16:51": {"l": "Surah An-Nahl, 16:51", "u": "https://quran.com/16/51", "ar": "۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَإِيَّٰىَ فَٱرْهَبُونِ ﴿٥١﴾", "tr": "And Allah has said, \"Do not take for yourselves two deities. He is but one God, so fear only Me.\" (51)", "a": "kalima-tawheed.html#q-16-51"}, "Q:57:22": {"l": "Surah Al-Hadid, 57:22", "u": "https://quran.com/57/22", "ar": "مَآ أَصَابَ مِن مُّصِيبَةٍۢ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍۢ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ ﴿٢٢﴾", "tr": "No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy - (22)", "a": "taqdeer.html#q-57-22-23"}, "Q:57:23": {"l": "Surah Al-Hadid, 57:23", "u": "https://quran.com/57/23", "ar": "لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍۢ فَخُورٍ ﴿٢٣﴾", "tr": "In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful - (23)", "a": "taqdeer.html#q-57-22-23"}, "H:bukhari:6403": {"l": "Sahih al-Bukhari, Hadith 6403", "u": "https://sunnah.com/bukhari:6403", "t": "La ilaha illallahu wahdahu la sharika lah… one hundred times", "k": "مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ", "a": "kalima-tawheed.html#h-bukhari-6403"}, "Q:2:255": {"l": "Surah Al-Baqara, 2:255", "u": "https://quran.com/2/255", "ar": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ ﴿٢٥٥﴾", "tr": "Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great. (255)", "a": "iman-billah.html#q-2-255"}, "H:bukhari:6018": {"l": "Sahih al-Bukhari, Hadith 6018", "u": "https://sunnah.com/bukhari:6018", "t": "The neighbour, the guest and the tongue", "k": "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ يُؤْذِ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ", "a": "ihsan.html#h-bukhari-6018"}, "Q:2:21-22": {"l": "Surah Al-Baqara, 2:21-22", "u": "https://quran.com/2/21-22", "ar": "يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿٢١﴾ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًۭا وَأَنتُمْ تَعْلَمُونَ ﴿٢٢﴾", "tr": "O mankind, worship your Lord, who created you and those before you, that you may become righteous - (21) [He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him]. (22)", "a": "iman-billah.html#q-2-21-22"}, "Q:6:162-163": {"l": "Surah Al-An'aam, 6:162-163", "u": "https://quran.com/6/162-163", "ar": "قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ ﴿١٦٢﴾ لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ ﴿١٦٣﴾", "tr": "Say, \"Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds. (162) No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims.\" (163)", "a": "maqsad-e-takhleeq.html#q-6-162-163"}, "Q:51:56": {"l": "Surah Adh-Dhaariyat, 51:56", "u": "https://quran.com/51/56", "ar": "وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾", "tr": "And I did not create the jinn and mankind except to worship Me. (56)", "a": "maqsad-e-takhleeq.html#q-51-56-58"}, "Q:65:3": {"l": "Surah At-Talaaq, 65:3", "u": "https://quran.com/65/3", "ar": "وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍۢ قَدْرًۭا ﴿٣﴾", "tr": "And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent. (3)", "a": "taqdeer.html#q-65-3"}, "Q:29:69": {"l": "Surah Al-Ankaboot, 29:69", "u": "https://quran.com/29/69", "ar": "وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ ﴿٦٩﴾", "tr": "And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good. (69)", "a": "ihsan.html#q-29-69"}, "Q:7:54": {"l": "Surah Al-A'raaf, 7:54", "u": "https://quran.com/7/54", "ar": "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ ﴿٥٤﴾", "tr": "Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds. (54)", "a": "iman-billah.html#q-7-54"}, "Q:43:26-28": {"l": "Surah Az-Zukhruf, 43:26-28", "u": "https://quran.com/43/26-28", "ar": "وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ ﴿٢٦﴾ إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ ﴿٢٧﴾ وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةًۭ فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ ﴿٢٨﴾", "tr": "And [mention, O Muhammad], when Abraham said to his father and his people, \"Indeed, I am disassociated from that which you worship (26) Except for He who created me; and indeed, He will guide me.\" (27) And he made it a word remaining among his descendants that they might return [to it]. (28)", "a": "kalima-tawheed.html#q-43-26-28"}, "Q:23:84-89": {"l": "Surah Al-Muminoon, 23:84-89", "u": "https://quran.com/23/84-89", "ar": "قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ ﴿٨٤﴾ سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَذَكَّرُونَ ﴿٨٥﴾ قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ ﴿٨٦﴾ سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَتَّقُونَ ﴿٨٧﴾ قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ ﴿٨٨﴾ سَيَقُولُونَ لِلَّهِ ۚ قُلْ فَأَنَّىٰ تُسْحَرُونَ ﴿٨٩﴾", "tr": "Say, [O Muhammad], \"To whom belongs the earth and whoever is in it, if you should know?\" (84) They will say, \"To Allah.\" Say, \"Then will you not remember?\" (85) Say, \"Who is Lord of the seven heavens and Lord of the Great Throne?\" (86) They will say, \"[They belong] to Allah.\" Say, \"Then will you not fear Him?\" (87) Say, \"In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?\" (88) They will say, \"[All belongs] to Allah.\" Say, \"Then how are you deluded?\" (89)", "a": "iman-billah.html#q-23-84-89"}, "H:bukhari:6557": {"l": "Sahih al-Bukhari, Hadith 6557", "u": "https://sunnah.com/bukhari:6557", "t": "The question to the person in Hell with the lightest punishment", "k": "أَرَدْتُ مِنْكَ أَهْوَنَ مِنْ هَذَا وَأَنْتَ فِي صُلْبِ آدَمَ أَنْ لاَ تُشْرِكَ بِي شَيْئًا", "a": "maqsad-e-takhleeq.html#h-bukhari-6557"}, "H:bukhari:3191": {"l": "Sahih al-Bukhari, Hadith 3191", "u": "https://sunnah.com/bukhari:3191", "t": "Allah existed and nothing else… and He wrote everything", "k": "وَكَتَبَ فِي الذِّكْرِ كُلَّ شَىْءٍ", "a": "taqdeer.html#h-bukhari-3191"}, "Q:37:96": {"l": "Surah As-Saaffaat, 37:96", "u": "https://quran.com/37/96", "ar": "وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ ﴿٩٦﴾", "tr": "While Allah created you and that which you do?\" (96)", "a": "taqdeer.html#q-37-96"}, "Q:43:28": {"l": "Surah Az-Zukhruf, 43:28", "u": "https://quran.com/43/28", "ar": "وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةًۭ فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ ﴿٢٨﴾", "tr": "And he made it a word remaining among his descendants that they might return [to it]. (28)", "a": "kalima-tawheed.html#q-43-26-28"}, "Q:57:22-23": {"l": "Surah Al-Hadid, 57:22-23", "u": "https://quran.com/57/22-23", "ar": "مَآ أَصَابَ مِن مُّصِيبَةٍۢ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍۢ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ ﴿٢٢﴾ لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍۢ فَخُورٍ ﴿٢٣﴾", "tr": "No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy - (22) In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful - (23)", "a": "taqdeer.html#q-57-22-23"}, "Q:25:2": {"l": "Surah Al-Furqaan, 25:2", "u": "https://quran.com/25/2", "ar": "ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًۭا وَلَمْ يَكُن لَّهُۥ شَرِيكٌۭ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍۢ فَقَدَّرَهُۥ تَقْدِيرًۭا ﴿٢﴾", "tr": "He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination. (2)", "a": "taqdeer.html#q-25-2"}, "H:muslim:2588": {"l": "Sahih Muslim, Hadith 2588", "u": "https://sunnah.com/muslim:2588", "t": "Charity does not decrease wealth; forgiveness increases honour", "k": "مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ", "a": "ihsan.html#h-muslim-2588"}, "Q:76:2": {"l": "Surah Al-Insaan, 76:2", "u": "https://quran.com/76/2", "ar": "إِنَّا خَلَقْنَا ٱلْإِنسَٰنَ مِن نُّطْفَةٍ أَمْشَاجٍۢ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعًۢا بَصِيرًا ﴿٢﴾", "tr": "Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing. (2)", "a": "maqsad-e-takhleeq.html#q-76-2"}, "Q:98:5": {"l": "Surah Al-Bayyina, 98:5", "u": "https://quran.com/98/5", "ar": "وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ ﴿٥﴾", "tr": "And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion. (5)", "a": "maqsad-e-takhleeq.html#q-98-5"}, "Q:75:36": {"l": "Surah Al-Qiyaama, 75:36", "u": "https://quran.com/75/36", "ar": "أَيَحْسَبُ ٱلْإِنسَٰنُ أَن يُتْرَكَ سُدًى ﴿٣٦﴾", "tr": "Does man think that he will be left neglected? (36)", "a": "maqsad-e-takhleeq.html#q-75-36"}, "H:muslim:2805": {"l": "Sahih Muslim, Hadith 2805", "u": "https://sunnah.com/muslim:2805", "t": "What was asked while in Adam's loins: do not associate partners", "k": "قَدْ أَرَدْتُ مِنْكَ أَهْوَنَ مِنْ هَذَا وَأَنْتَ فِي صُلْبِ آدَمَ أَنْ لاَ تُشْرِكَ", "a": "maqsad-e-takhleeq.html#h-muslim-2805"}, "H:bukhari:6000": {"l": "Sahih al-Bukhari, Hadith 6000", "u": "https://sunnah.com/bukhari:6000", "t": "Mercy in one hundred parts", "k": "جَعَلَ اللَّهُ الرَّحْمَةَ مِائَةَ جُزْءٍ، فَأَمْسَكَ عِنْدَهُ تِسْعَةً وَتِسْعِينَ جُزْءًا، وَأَنْزَلَ فِي الأَرْضِ جُزْءًا وَاحِدًا", "a": "iman-billah.html#h-bukhari-6000"}, "Q:11:6": {"l": "Surah Hud, 11:6", "u": "https://quran.com/11/6", "ar": "۞ وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّۭ فِى كِتَٰبٍۢ مُّبِينٍۢ ﴿٦﴾", "tr": "And there is no creature on earth but that upon Allah is its provision, and He knows its place of dwelling and place of storage. All is in a clear register. (6)", "a": "taqdeer.html#q-11-6"}, "Q:17:23": {"l": "Surah Al-Israa, 17:23", "u": "https://quran.com/17/23", "ar": "۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا ﴿٢٣﴾", "tr": "And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], \"uff,\" and do not repel them but speak to them a noble word. (23)", "a": "ihsan.html#q-17-23"}, "Q:55:60": {"l": "Surah Ar-Rahmaan, 55:60", "u": "https://quran.com/55/60", "ar": "هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ ﴿٦٠﴾", "tr": "Is the reward for good [anything] but good? (60)", "a": "ihsan.html#q-55-60"}, "H:bukhari:6616": {"l": "Sahih al-Bukhari, Hadith 6616", "u": "https://sunnah.com/bukhari:6616", "t": "Seeking refuge from an evil decree (su' al-qada')", "k": "تَعَوَّذُوا بِاللَّهِ مِنْ جَهْدِ الْبَلاَءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ", "a": "taqdeer.html#h-bukhari-6616"}, "Q:47:19": {"l": "Surah Muhammad, 47:19", "u": "https://quran.com/47/19", "ar": "فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ ﴿١٩﴾", "tr": "So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place. (19)", "a": "kalima-tawheed.html#q-47-19"}, "Q:26:218": {"l": "Surah Ash-Shu'araa, 26:218", "u": "https://quran.com/26/218", "ar": "ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ ﴿٢١٨﴾", "tr": "Who sees you when you arise (218)", "a": "ihsan.html#q-26-217-220"}, "H:bukhari:8": {"l": "Sahih al-Bukhari, Hadith 8", "u": "https://sunnah.com/bukhari:8", "t": "Islam is built upon five", "k": "بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ", "a": "kalima-tawheed.html#h-bukhari-8"}, "Q:16:36": {"l": "Surah An-Nahl, 16:36", "u": "https://quran.com/16/36", "ar": "وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍۢ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ ﴿٣٦﴾", "tr": "And We certainly sent into every nation a messenger, [saying], \"Worship Allah and avoid Taghut.\" And among them were those whom Allah guided, and among them were those upon whom error was [deservedly] decreed. So proceed through the earth and observe how was the end of the deniers. (36)", "a": "maqsad-e-takhleeq.html#q-16-36"}, "Q:16:90": {"l": "Surah An-Nahl, 16:90", "u": "https://quran.com/16/90", "ar": "۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ ﴿٩٠﴾", "tr": "Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded. (90)", "a": "ihsan.html#q-16-90"}, "H:bukhari:128": {"l": "Sahih al-Bukhari, Hadith 128", "u": "https://sunnah.com/bukhari:128", "t": "Testifying sincerely from the heart", "k": "مَا مِنْ أَحَدٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ صِدْقًا مِنْ قَلْبِهِ إِلاَّ حَرَّمَهُ اللَّهُ عَلَى النَّارِ", "a": "kalima-tawheed.html#h-bukhari-128"}, "H:bukhari:1": {"l": "Sahih al-Bukhari, Hadith 1", "u": "https://sunnah.com/bukhari:1", "t": "Deeds are judged by intentions", "k": "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى", "a": "maqsad-e-takhleeq.html#h-bukhari-1"}, "Q:2:21": {"l": "Surah Al-Baqara, 2:21", "u": "https://quran.com/2/21", "ar": "يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿٢١﴾", "tr": "O mankind, worship your Lord, who created you and those before you, that you may become righteous - (21)", "a": "maqsad-e-takhleeq.html#q-2-21"}, "Q:76:30": {"l": "Surah Al-Insaan, 76:30", "u": "https://quran.com/76/30", "ar": "وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا ﴿٣٠﴾", "tr": "And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise. (30)", "a": "taqdeer.html#q-76-30"}, "Q:4:36": {"l": "Surah An-Nisaa, 4:36", "u": "https://quran.com/4/36", "ar": "۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًۭا فَخُورًا ﴿٣٦﴾", "tr": "Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful. (36)", "a": "ihsan.html#q-4-36"}, "H:bukhari:6412": {"l": "Sahih al-Bukhari, Hadith 6412", "u": "https://sunnah.com/bukhari:6412", "t": "Two blessings: health and free time", "k": "نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ، الصِّحَّةُ وَالْفَرَاغُ", "a": "maqsad-e-takhleeq.html#h-bukhari-6412"}, "H:bukhari:99": {"l": "Sahih al-Bukhari, Hadith 99", "u": "https://sunnah.com/bukhari:99", "t": "Most deserving of intercession: one who says it purely from the heart", "k": "أَسْعَدُ النَّاسِ بِشَفَاعَتِي يَوْمَ الْقِيَامَةِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، خَالِصًا مِنْ قَلْبِهِ أَوْ نَفْسِهِ", "a": "kalima-tawheed.html#h-bukhari-99"}, "H:muslim:2653b": {"l": "Sahih Muslim, Hadith 2653", "u": "https://sunnah.com/muslim:2653b", "t": "Decrees written fifty thousand years before the heavens and earth", "k": "كَتَبَ اللَّهُ مَقَادِيرَ الْخَلاَئِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ", "a": "taqdeer.html#h-muslim-2653b"}, "Q:112:1-4": {"l": "Surah Al-Ikhlaas, 112:1-4", "u": "https://quran.com/112/1-4", "ar": "قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿٤﴾", "tr": "Say, \"He is Allah, [who is] One, (1) Allah, the Eternal Refuge. (2) He neither begets nor is born, (3) Nor is there to Him any equivalent.\" (4)", "a": "iman-billah.html#q-112-1-4"}, "H:muslim:2664": {"l": "Sahih Muslim, Hadith 2664", "u": "https://sunnah.com/muslim:2664", "t": "The strong believer… and do not say \"if only\"", "k": "احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلاَ تَعْجِزْ … قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ", "a": "taqdeer.html#h-muslim-2664"}, "H:muslim:2656": {"l": "Sahih Muslim, Hadith 2656", "u": "https://sunnah.com/muslim:2656", "t": "Everything is by decree, even incapacity and ability", "k": "كُلُّ شَىْءٍ بِقَدَرٍ حَتَّى الْعَجْزُ وَالْكَيْسُ أَوِ الْكَيْسُ وَالْعَجْزُ", "a": "taqdeer.html#h-muslim-2656"}, "Q:59:22-24": {"l": "Surah Al-Hashr, 59:22-24", "u": "https://quran.com/59/22-24", "ar": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ۖ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ ﴿٢٢﴾ هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ ﴿٢٣﴾ هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ ﴿٢٤﴾", "tr": "He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful. (22) He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him. (23) He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise. (24)", "a": "iman-billah.html#q-59-22-24"}, "Q:35:3": {"l": "Surah Faatir, 35:3", "u": "https://quran.com/35/3", "ar": "يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ ۚ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ ﴿٣﴾", "tr": "O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded? (3)", "a": "iman-billah.html#q-35-3"}, "H:muslim:2577": {"l": "Sahih Muslim, Hadith 2577", "u": "https://sunnah.com/muslim:2577", "t": "Hadith Qudsi: \"O My servants!\"", "k": "يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلاَ تَظَالَمُوا … مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا", "a": "maqsad-e-takhleeq.html#h-muslim-2577"}, "H:bukhari:7405": {"l": "Sahih al-Bukhari, Hadith 7405", "u": "https://sunnah.com/bukhari:7405", "t": "I am as My servant thinks of Me", "k": "أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي", "a": "iman-billah.html#h-bukhari-7405"}, "H:muslim:47": {"l": "Sahih Muslim, Hadith 47", "u": "https://sunnah.com/muslim:47", "t": "Speak good or remain silent", "k": "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ", "a": "ihsan.html#h-muslim-47"}, "H:bukhari:6614": {"l": "Sahih al-Bukhari, Hadith 6614", "u": "https://sunnah.com/bukhari:6614", "t": "The argument between Adam and Musa (peace be upon them)", "k": "أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَ اللَّهُ عَلَىَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً", "a": "taqdeer.html#h-bukhari-6614"}, "H:bukhari:3208": {"l": "Sahih al-Bukhari, Hadith 3208", "u": "https://sunnah.com/bukhari:3208", "t": "Four things written in the mother's womb", "k": "فَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ، وَيُقَالُ لَهُ اكْتُبْ عَمَلَهُ وَرِزْقَهُ وَأَجَلَهُ وَشَقِيٌّ أَوْ سَعِيدٌ", "a": "taqdeer.html#h-bukhari-3208"}, "Q:6:59": {"l": "Surah Al-An'aam, 6:59", "u": "https://quran.com/6/59", "ar": "۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍۢ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍۢ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍۢ ﴿٥٩﴾", "tr": "And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record. (59)", "a": "taqdeer.html#q-6-59"}, "Q:51:56-58": {"l": "Surah Adh-Dhaariyat, 51:56-58", "u": "https://quran.com/51/56-58", "ar": "وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾ مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ ﴿٥٧﴾ إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ ﴿٥٨﴾", "tr": "And I did not create the jinn and mankind except to worship Me. (56) I do not want from them any provision, nor do I want them to feed Me. (57) Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength. (58)", "a": "maqsad-e-takhleeq.html#q-51-56-58"}, "H:bukhari:6011": {"l": "Sahih al-Bukhari, Hadith 6011", "u": "https://sunnah.com/bukhari:6011", "t": "The believers are like one body", "k": "تَرَى الْمُؤْمِنِينَ فِي تَرَاحُمِهِمْ وَتَوَادِّهِمْ وَتَعَاطُفِهِمْ كَمَثَلِ الْجَسَدِ", "a": "ihsan.html#h-bukhari-6011"}, "Q:10:31": {"l": "Surah Yunus, 10:31", "u": "https://quran.com/10/31", "ar": "قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ ﴿٣١﴾", "tr": "Say, \"Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?\" They will say, \"Allah,\" so say, \"Then will you not fear Him?\" (31)", "a": "iman-billah.html#q-10-31"}, "Q:57:4": {"l": "Surah Al-Hadid, 57:4", "u": "https://quran.com/57/4", "ar": "هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ ﴿٤﴾", "tr": "It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allah, of what you do, is Seeing. (4)", "a": "ihsan.html#q-57-4"}, "Q:43:27": {"l": "Surah Az-Zukhruf, 43:27", "u": "https://quran.com/43/27", "ar": "إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ ﴿٢٧﴾", "tr": "Except for He who created me; and indeed, He will guide me.\" (27)", "a": "kalima-tawheed.html#q-43-26-28"}, "Q:22:70": {"l": "Surah Al-Hajj, 22:70", "u": "https://quran.com/22/70", "ar": "أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ ﴿٧٠﴾", "tr": "Do you not know that Allah knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allah, is easy. (70)", "a": "taqdeer.html#q-22-70"}, "Q:2:195": {"l": "Surah Al-Baqara, 2:195", "u": "https://quran.com/2/195", "ar": "وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ ﴿١٩٥﴾", "tr": "And spend in the way of Allah and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allah loves the doers of good. (195)", "a": "ihsan.html#q-2-195"}, "Q:43:26": {"l": "Surah Az-Zukhruf, 43:26", "u": "https://quran.com/43/26", "ar": "وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ ﴿٢٦﴾", "tr": "And [mention, O Muhammad], when Abraham said to his father and his people, \"Indeed, I am disassociated from that which you worship (26)", "a": "kalima-tawheed.html#q-43-26-28"}, "Q:4:125": {"l": "Surah An-Nisaa, 4:125", "u": "https://quran.com/4/125", "ar": "وَمَنْ أَحْسَنُ دِينًۭا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًۭا ﴿١٢٥﴾", "tr": "And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend. (125)", "a": "ihsan.html#q-4-125"}, "Q:67:2": {"l": "Surah Al-Mulk, 67:2", "u": "https://quran.com/67/2", "ar": "ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ ﴿٢﴾", "tr": "[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving - (2)", "a": "maqsad-e-takhleeq.html#q-67-2"}, "Q:54:49": {"l": "Surah Al-Qamar, 54:49", "u": "https://quran.com/54/49", "ar": "إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍۢ ﴿٤٩﴾", "tr": "Indeed, all things We created with predestination. (49)", "a": "taqdeer.html#q-54-49"}, "Q:51:57-58": {"l": "Surah Adh-Dhaariyat, 51:57-58", "u": "https://quran.com/51/57-58", "ar": "مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ ﴿٥٧﴾ إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ ﴿٥٨﴾", "tr": "I do not want from them any provision, nor do I want them to feed Me. (57) Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength. (58)", "a": "maqsad-e-takhleeq.html#q-51-56-58"}, "H:bukhari:2856": {"l": "Sahih al-Bukhari, Hadith 2856", "u": "https://sunnah.com/bukhari:2856", "t": "Allah's right over His servants, and the servants' right over Allah", "k": "فَإِنَّ حَقَّ اللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلاَ يُشْرِكُوا بِهِ شَيْئًا، وَحَقَّ الْعِبَادِ عَلَى اللَّهِ أَنْ لاَ يُعَذِّبَ مَنْ لاَ يُشْرِكُ بِهِ شَيْئًا", "a": "maqsad-e-takhleeq.html#h-bukhari-2856"}, "H:bukhari:1237": {"l": "Sahih al-Bukhari, Hadith 1237", "u": "https://sunnah.com/bukhari:1237", "t": "Whoever dies without associating partners", "k": "أَنَّهُ مَنْ مَاتَ مِنْ أُمَّتِي لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ", "a": "kalima-tawheed.html#h-bukhari-1237"}, "H:bukhari:44": {"l": "Sahih al-Bukhari, Hadith 44", "u": "https://sunnah.com/bukhari:44", "t": "Even with an atom's weight of good in the heart", "k": "يَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ", "a": "kalima-tawheed.html#h-bukhari-44"}, "Q:52:35-36": {"l": "Surah At-Tur, 52:35-36", "u": "https://quran.com/52/35-36", "ar": "أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ ﴿٣٥﴾ أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ ﴿٣٦﴾", "tr": "Or were they created by nothing, or were they the creators [of themselves]? (35) Or did they create the heavens and the earth? Rather, they are not certain. (36)", "a": "iman-billah.html#q-52-35-36"}, "H:bukhari:5999": {"l": "Sahih al-Bukhari, Hadith 5999", "u": "https://sunnah.com/bukhari:5999", "t": "More merciful to His servants than a mother", "k": "لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ بِوَلَدِهَا", "a": "iman-billah.html#h-bukhari-5999"}, "H:bukhari:1145": {"l": "Sahih al-Bukhari, Hadith 1145", "u": "https://sunnah.com/bukhari:1145", "t": "Descending in the last third of the night", "k": "مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ", "a": "iman-billah.html#h-bukhari-1145"}, "H:bukhari:7375": {"l": "Sahih al-Bukhari, Hadith 7375", "u": "https://sunnah.com/bukhari:7375", "t": "Loving Surat al-Ikhlas: it is the description of ar-Rahman", "k": "أَخْبِرُوهُ أَنَّ اللَّهَ يُحِبُّهُ", "a": "iman-billah.html#h-bukhari-7375"}, "Q:2:165": {"l": "Surah Al-Baqara, 2:165", "u": "https://quran.com/2/165", "ar": "وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًۭا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّۭا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًۭا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ ﴿١٦٥﴾", "tr": "And [yet], among the people are those who take other than Allah as equals [to Him]. They love them as they [should] love Allah. But those who believe are stronger in love for Allah. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allah and that Allah is severe in punishment. (165)", "a": "kalima-tawheed.html#q-2-165"}, "Q:3:134": {"l": "Surah Aal-i-Imraan, 3:134", "u": "https://quran.com/3/134", "ar": "ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ ﴿١٣٤﴾", "tr": "Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good; (134)", "a": "ihsan.html#q-3-134"}, "H:muslim:2713": {"l": "Sahih Muslim, Hadith 2713", "u": "https://sunnah.com/muslim:2713", "t": "You are the First, the Last, the Manifest, the Hidden", "k": "اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَىْءٍ … أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَىْءٌ", "a": "iman-billah.html#h-muslim-2713"}, "Q:42:11": {"l": "Surah Ash-Shura, 42:11", "u": "https://quran.com/42/11", "ar": "فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًۭا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ ﴿١١﴾", "tr": "[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing. (11)", "a": "iman-billah.html#q-42-11"}, "Q:2:112": {"l": "Surah Al-Baqara, 2:112", "u": "https://quran.com/2/112", "ar": "بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿١١٢﴾", "tr": "Yes [on the contrary], whoever submits his face in Islam to Allah while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve. (112)", "a": "ihsan.html#q-2-112"}, "Q:52:35": {"l": "Surah At-Tur, 52:35", "u": "https://quran.com/52/35", "ar": "أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ ﴿٣٥﴾", "tr": "Or were they created by nothing, or were they the creators [of themselves]? (35)", "a": "iman-billah.html#q-52-35-36"}, "H:bukhari:6384": {"l": "Sahih al-Bukhari, Hadith 6384", "u": "https://sunnah.com/bukhari:6384", "t": "You are not calling one who is deaf or absent", "k": "فَإِنَّكُمْ لاَ تَدْعُونَ أَصَمَّ وَلاَ غَائِبًا، وَلَكِنْ تَدْعُونَ سَمِيعًا بَصِيرًا", "a": "iman-billah.html#h-bukhari-6384"}, "H:bukhari:50": {"l": "Sahih al-Bukhari, Hadith 50", "u": "https://sunnah.com/bukhari:50", "t": "Hadith of Jibril (narrated by Abu Hurairah)", "k": "الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَبِلِقَائِهِ وَرُسُلِهِ، وَتُؤْمِنَ بِالْبَعْثِ … أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ", "a": "ihsan.html#h-bukhari-50"}, "Q:23:115-116": {"l": "Surah Al-Muminoon, 23:115-116", "u": "https://quran.com/23/115-116", "ar": "أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ﴿١١٥﴾ فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ ﴿١١٦﴾", "tr": "Then did you think that We created you uselessly and that to Us you would not be returned?\" (115) So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne. (116)", "a": "maqsad-e-takhleeq.html#q-23-115-116"}, "H:muslim:2564c": {"l": "Sahih Muslim, Hadith 2564", "u": "https://sunnah.com/muslim:2564c", "t": "Allah looks at hearts and deeds", "k": "إِنَّ اللَّهَ لاَ يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ", "a": "ihsan.html#h-muslim-2564c"}, "Q:2:163": {"l": "Surah Al-Baqara, 2:163", "u": "https://quran.com/2/163", "ar": "وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ ﴿١٦٣﴾", "tr": "And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful. (163)", "a": "iman-billah.html#q-2-163"}, "Q:9:51": {"l": "Surah At-Tawba, 9:51", "u": "https://quran.com/9/51", "ar": "قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ ﴿٥١﴾", "tr": "Say, \"Never will we be struck except by what Allah has decreed for us; He is our protector.\" And upon Allah let the believers rely. (51)", "a": "taqdeer.html#q-9-51"}, "Q:2:256": {"l": "Surah Al-Baqara, 2:256", "u": "https://quran.com/2/256", "ar": "لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿٢٥٦﴾", "tr": "There shall be no compulsion in [acceptance of] the religion. The right course has become clear from the wrong. So whoever disbelieves in Taghut and believes in Allah has grasped the most trustworthy handhold with no break in it. And Allah is Hearing and Knowing. (256)", "a": "kalima-tawheed.html#q-2-256"}, "Q:37:35": {"l": "Surah As-Saaffaat, 37:35", "u": "https://quran.com/37/35", "ar": "إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ ﴿٣٥﴾", "tr": "Indeed they, when it was said to them, \"There is no deity but Allah,\" were arrogant (35)", "a": "kalima-tawheed.html#q-37-35"}, "H:muslim:26": {"l": "Sahih Muslim, Hadith 26", "u": "https://sunnah.com/muslim:26", "t": "Whoever dies knowing there is no god but Allah", "k": "مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ", "a": "kalima-tawheed.html#h-muslim-26"}, "Q:2:22": {"l": "Surah Al-Baqara, 2:22", "u": "https://quran.com/2/22", "ar": "ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًۭا وَأَنتُمْ تَعْلَمُونَ ﴿٢٢﴾", "tr": "[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him]. (22)", "a": "iman-billah.html#q-2-21-22"}, "Q:36:12": {"l": "Surah Yaseen, 36:12", "u": "https://quran.com/36/12", "ar": "إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ ۚ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍۢ مُّبِينٍۢ ﴿١٢﴾", "tr": "Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register. (12)", "a": "taqdeer.html#q-36-12"}, "H:bukhari:4949": {"l": "Sahih al-Bukhari, Hadith 4949", "u": "https://sunnah.com/bukhari:4949", "t": "Do deeds; for each it is made easy", "k": "مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ وَقَدْ كُتِبَ مَقْعَدُهُ مِنَ النَّارِ وَمَقْعَدُهُ مِنَ الْجَنَّةِ … اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ", "a": "taqdeer.html#h-bukhari-4949"}, "Q:39:62": {"l": "Surah Az-Zumar, 39:62", "u": "https://quran.com/39/62", "ar": "ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ ﴿٦٢﴾", "tr": "Allah is the Creator of all things, and He is, over all things, Disposer of affairs. (62)", "a": "iman-billah.html#q-39-62"}, "H:bukhari:6407": {"l": "Sahih al-Bukhari, Hadith 6407", "u": "https://sunnah.com/bukhari:6407", "t": "One who remembers his Lord and one who does not: the living and the dead", "k": "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ مَثَلُ الْحَىِّ وَالْمَيِّتِ", "a": "maqsad-e-takhleeq.html#h-bukhari-6407"}, "Q:21:25": {"l": "Surah Al-Anbiyaa, 21:25", "u": "https://quran.com/21/25", "ar": "وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ ﴿٢٥﴾", "tr": "And We sent not before you any messenger except that We revealed to him that, \"There is no deity except Me, so worship Me.\" (25)", "a": "maqsad-e-takhleeq.html#q-21-25"}, "H:bukhari:7382": {"l": "Sahih al-Bukhari, Hadith 7382", "u": "https://sunnah.com/bukhari:7382", "t": "I am the King; where are the kings of the earth?", "k": "يَقْبِضُ اللَّهُ الأَرْضَ يَوْمَ الْقِيَامَةِ، وَيَطْوِي السَّمَاءَ بِيَمِينِهِ ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَيْنَ مُلُوكُ الأَرْضِ", "a": "iman-billah.html#h-bukhari-7382"}, "Q:28:76-77": {"l": "Surah Al-Qasas, 28:76-77", "u": "https://quran.com/28/76-77", "ar": "۞ إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ ۖ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ ﴿٧٦﴾ وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْءَاخِرَةَ ۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا ۖ وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ ۖ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ ﴿٧٧﴾", "tr": "Indeed, Qarun was from the people of Moses, but he tyrannized them. And We gave him of treasures whose keys would burden a band of strong men; thereupon his people said to him, \"Do not exult. Indeed, Allah does not like the exultant. (76) But seek, through that which Allah has given you, the home of the Hereafter; and [yet], do not forget your share of the world. And do good as Allah has done good to you. And desire not corruption in the land. Indeed, Allah does not like corrupters.\" (77)", "a": "ihsan.html#q-28-76-77"}, "Q:20:14": {"l": "Surah Taa-Haa, 20:14", "u": "https://quran.com/20/14", "ar": "إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ ﴿١٤﴾", "tr": "Indeed, I am Allah. There is no deity except Me, so worship Me and establish prayer for My remembrance. (14)", "a": "iman-billah.html#q-20-14"}, "H:bukhari:3194": {"l": "Sahih al-Bukhari, Hadith 3194", "u": "https://sunnah.com/bukhari:3194", "t": "My mercy prevails over My anger", "k": "لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ، فَهْوَ عِنْدَهُ فَوْقَ الْعَرْشِ إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي", "a": "iman-billah.html#h-bukhari-3194"}, "Q:49:15": {"l": "Surah Al-Hujuraat, 49:15", "u": "https://quran.com/49/15", "ar": "إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ ﴿١٥﴾", "tr": "The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful. (15)", "a": "kalima-tawheed.html#q-49-15"}, "H:muslim:1955": {"l": "Sahih Muslim, Hadith 1955", "u": "https://sunnah.com/muslim:1955", "t": "Allah has prescribed ihsan in everything", "k": "إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَىْءٍ … وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ فَلْيُرِحْ ذَبِيحَتَهُ", "a": "ihsan.html#h-muslim-1955"}, "Q:1:2": {"l": "Surah Al-Faatiha, 1:2", "u": "https://quran.com/1/2", "ar": "ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ ﴿٢﴾", "tr": "[All] praise is [due] to Allah, Lord of the worlds - (2)", "a": "iman-billah.html#q-1-2"}, "Q:3:18": {"l": "Surah Aal-i-Imraan, 3:18", "u": "https://quran.com/3/18", "ar": "شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ ﴿١٨﴾", "tr": "Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise. (18)", "a": "kalima-tawheed.html#q-3-18"}, "Q:7:180": {"l": "Surah Al-A'raaf, 7:180", "u": "https://quran.com/7/180", "ar": "وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ ﴿١٨٠﴾", "tr": "And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing. (180)", "a": "iman-billah.html#q-7-180"}, "Q:21:22": {"l": "Surah Al-Anbiyaa, 21:22", "u": "https://quran.com/21/22", "ar": "لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ ﴿٢٢﴾", "tr": "Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe. (22)", "a": "kalima-tawheed.html#q-21-22"}, "Q:22:62": {"l": "Surah Al-Hajj, 22:62", "u": "https://quran.com/22/62", "ar": "ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ ﴿٦٢﴾", "tr": "That is because Allah is the Truth, and that which they call upon other than Him is falsehood, and because Allah is the Most High, the Grand. (62)", "a": "kalima-tawheed.html#q-22-62"}, "Q:30:30": {"l": "Surah Ar-Room, 30:30", "u": "https://quran.com/30/30", "ar": "فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًۭا ۚ فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا ۚ لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ ﴿٣٠﴾", "tr": "So direct your face toward the religion, inclining to truth. [Adhere to] the fitrah of Allah upon which He has created [all] people. No change should there be in the creation of Allah. That is the correct religion, but most of the people do not know. (30)", "a": "maqsad-e-takhleeq.html#q-30-30"}, "Q:50:16": {"l": "Surah Qaaf, 50:16", "u": "https://quran.com/50/16", "ar": "وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ ﴿١٦﴾", "tr": "And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein (16)", "a": "ihsan.html#q-50-16"}, "H:bukhari:6596": {"l": "Sahih al-Bukhari, Hadith 6596", "u": "https://sunnah.com/bukhari:6596", "t": "Each does the deeds for which he was created", "k": "فَلِمَ يَعْمَلُ الْعَامِلُونَ … كُلٌّ يَعْمَلُ لِمَا خُلِقَ لَهُ ـ أَوْ لِمَا يُسِّرَ لَهُ", "a": "taqdeer.html#h-bukhari-6596"}, "H:bukhari:5971": {"l": "Sahih al-Bukhari, Hadith 5971", "u": "https://sunnah.com/bukhari:5971", "t": "Most deserving of good companionship: your mother", "k": "أُمُّكَ … ثُمَّ أَبُوكَ", "a": "ihsan.html#h-bukhari-5971"}, "Q:18:30": {"l": "Surah Al-Kahf, 18:30", "u": "https://quran.com/18/30", "ar": "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا ﴿٣٠﴾", "tr": "Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds. (30)", "a": "ihsan.html#q-18-30"}, "Q:64:11": {"l": "Surah At-Taghaabun, 64:11", "u": "https://quran.com/64/11", "ar": "مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ ﴿١١﴾", "tr": "No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things. (11)", "a": "taqdeer.html#q-64-11"}, "H:muslim:27": {"l": "Sahih Muslim, Hadith 27", "u": "https://sunnah.com/muslim:27", "t": "Meeting Allah with both testimonies, free of doubt", "k": "أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ لاَ يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فِيهِمَا إِلاَّ دَخَلَ الْجَنَّةَ", "a": "kalima-tawheed.html#h-muslim-27"}, "Q:7:172": {"l": "Surah Al-A'raaf, 7:172", "u": "https://quran.com/7/172", "ar": "وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ ﴿١٧٢﴾", "tr": "And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], \"Am I not your Lord?\" They said, \"Yes, we have testified.\" [This] - lest you should say on the day of Resurrection, \"Indeed, we were of this unaware.\" (172)", "a": "maqsad-e-takhleeq.html#q-7-172"}, "Q:60:4": {"l": "Surah Al-Mumtahana, 60:4", "u": "https://quran.com/60/4", "ar": "قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌۭ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍۢ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ ﴿٤﴾", "tr": "There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, \"Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone\" except for the saying of Abraham to his father, \"I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination. (4)", "a": "kalima-tawheed.html#q-60-4"}, "H:bukhari:1385": {"l": "Sahih al-Bukhari, Hadith 1385", "u": "https://sunnah.com/bukhari:1385", "t": "Every child is born upon the fitrah", "k": "كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ أَوْ يُمَجِّسَانِهِ", "a": "maqsad-e-takhleeq.html#h-bukhari-1385"}, "Q:39:2-3": {"l": "Surah Az-Zumar, 39:2-3", "u": "https://quran.com/39/2-3", "ar": "إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًۭا لَّهُ ٱلدِّينَ ﴿٢﴾ أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌۭ كَفَّارٌۭ ﴿٣﴾", "tr": "Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion. (2) Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], \"We only worship them that they may bring us nearer to Allah in position.\" Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever. (3)", "a": "kalima-tawheed.html#q-39-2-3"}, "Q:33:38": {"l": "Surah Al-Ahzaab, 33:38", "u": "https://quran.com/33/38", "ar": "مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍۢ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ ۖ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۚ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًۭا مَّقْدُورًا ﴿٣٨﴾", "tr": "There is not to be upon the Prophet any discomfort concerning that which Allah has imposed upon him. [This is] the established way of Allah with those [prophets] who have passed on before. And ever is the command of Allah a destiny decreed. (38)", "a": "taqdeer.html#q-33-38"}, "H:bukhari:4477": {"l": "Sahih al-Bukhari, Hadith 4477", "u": "https://sunnah.com/bukhari:4477", "t": "The greatest sin: setting up a rival to Allah", "k": "أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ", "a": "iman-billah.html#h-bukhari-4477"}, "Q:18:7": {"l": "Surah Al-Kahf, 18:7", "u": "https://quran.com/18/7", "ar": "إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةًۭ لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًۭا ﴿٧﴾", "tr": "Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed. (7)", "a": "maqsad-e-takhleeq.html#q-18-7"}, "Q:15:99": {"l": "Surah Al-Hijr, 15:99", "u": "https://quran.com/15/99", "ar": "وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ ﴿٩٩﴾", "tr": "And worship your Lord until there comes to you the certainty (death). (99)", "a": "maqsad-e-takhleeq.html#q-15-99"}, "H:muslim:2999": {"l": "Sahih Muslim, Hadith 2999", "u": "https://sunnah.com/muslim:2999", "t": "The affair of the believer is amazing: gratitude and patience", "k": "عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ … إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ", "a": "taqdeer.html#h-muslim-2999"}, "H:muslim:35b": {"l": "Sahih Muslim, Hadith 35", "u": "https://sunnah.com/muslim:35b", "t": "The highest branch of faith: La ilaha illallah", "k": "الإِيمَانُ بِضْعٌ وَسَبْعُونَ أَوْ بِضْعٌ وَسِتُّونَ شُعْبَةً فَأَفْضَلُهَا قَوْلُ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ", "a": "kalima-tawheed.html#h-muslim-35b"}, "Q:10:61": {"l": "Surah Yunus, 10:61", "u": "https://quran.com/10/61", "ar": "وَمَا تَكُونُ فِى شَأْنٍۢ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍۢ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍ ﴿٦١﴾", "tr": "And, [O Muhammad], you are not [engaged] in any matter or recite any of the Qur'an and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom's weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register. (61)", "a": "ihsan.html#q-10-61"}, "Q:26:217-220": {"l": "Surah Ash-Shu'araa, 26:217-220", "u": "https://quran.com/26/217-220", "ar": "وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ ﴿٢١٧﴾ ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ ﴿٢١٨﴾ وَتَقَلُّبَكَ فِى ٱلسَّٰجِدِينَ ﴿٢١٩﴾ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ ﴿٢٢٠﴾", "tr": "And rely upon the Exalted in Might, the Merciful, (217) Who sees you when you arise (218) And your movement among those who prostrate. (219) Indeed, He is the Hearing, the Knowing. (220)", "a": "ihsan.html#q-26-217-220"}, "Q:1:5": {"l": "Surah Al-Faatiha, 1:5", "u": "https://quran.com/1/5", "ar": "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾", "tr": "It is You we worship and You we ask for help. (5)", "a": "maqsad-e-takhleeq.html#q-1-5"}, "H:bukhari:7376": {"l": "Sahih al-Bukhari, Hadith 7376", "u": "https://sunnah.com/bukhari:7376", "t": "Whoever is not merciful to people", "k": "لاَ يَرْحَمُ اللَّهُ مَنْ لاَ يَرْحَمُ النَّاسَ", "a": "ihsan.html#h-bukhari-7376"}, "H:bukhari:2736": {"l": "Sahih al-Bukhari, Hadith 2736", "u": "https://sunnah.com/bukhari:2736", "t": "The ninety-nine names of Allah", "k": "إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمَا مِائَةً إِلاَّ وَاحِدًا مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ", "a": "iman-billah.html#h-bukhari-2736"}, "H:muslim:179": {"l": "Sahih Muslim, Hadith 179", "u": "https://sunnah.com/muslim:179", "t": "Allah does not sleep; His veil is light", "k": "إِنَّ اللَّهَ عَزَّ وَجَلَّ لاَ يَنَامُ وَلاَ يَنْبَغِي لَهُ أَنْ يَنَامَ", "a": "iman-billah.html#h-muslim-179"}, "Q:39:3": {"l": "Surah Az-Zumar, 39:3", "u": "https://quran.com/39/3", "ar": "أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌۭ كَفَّارٌۭ ﴿٣﴾", "tr": "Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], \"We only worship them that they may bring us nearer to Allah in position.\" Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever. (3)", "a": "kalima-tawheed.html#q-39-2-3"}, "H:bukhari:2989": {"l": "Sahih al-Bukhari, Hadith 2989", "u": "https://sunnah.com/bukhari:2989", "t": "Charity due on every joint: justice, help, a good word", "k": "كُلُّ سُلاَمَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ … وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ", "a": "ihsan.html#h-bukhari-2989"}, "H:muslim:23": {"l": "Sahih Muslim, Hadith 23", "u": "https://sunnah.com/muslim:23", "t": "Saying La ilaha illallah and rejecting worship of other than Allah", "k": "مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ حَرُمَ مَالُهُ وَدَمُهُ وَحِسَابُهُ عَلَى اللَّهِ", "a": "kalima-tawheed.html#h-muslim-23"}, "H:bukhari:6502": {"l": "Sahih al-Bukhari, Hadith 6502", "u": "https://sunnah.com/bukhari:6502", "t": "Nearness to Allah through obligatory and voluntary deeds", "k": "وَمَا تَقَرَّبَ إِلَىَّ عَبْدِي بِشَىْءٍ أَحَبَّ إِلَىَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَىَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ", "a": "maqsad-e-takhleeq.html#h-bukhari-6502"}, "Q:6:162": {"l": "Surah Al-An'aam, 6:162", "u": "https://quran.com/6/162", "ar": "قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ ﴿١٦٢﴾", "tr": "Say, \"Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds. (162)", "a": "maqsad-e-takhleeq.html#q-6-162-163"}, "H:muslim:8": {"l": "Sahih Muslim, Hadith 8", "u": "https://sunnah.com/muslim:8", "t": "Hadith of Jibril (narrated by 'Umar)", "k": "أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ … أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ", "a": "taqdeer.html#h-muslim-8"}, "H:muslim:30": {"l": "Sahih Muslim, Hadith 30", "u": "https://sunnah.com/muslim:30", "t": "From Mu'adh ibn Jabal: Allah's right over His servants", "k": "يَعْبُدُوهُ وَلاَ يُشْرِكُوا بِهِ شَيْئًا … هَلْ تَدْرِي مَا حَقُّ الْعِبَادِ عَلَى اللَّهِ إِذَا فَعَلُوا ذَلِكَ", "a": "maqsad-e-takhleeq.html#h-muslim-30"}, "H:bukhari:3435": {"l": "Sahih al-Bukhari, Hadith 3435", "u": "https://sunnah.com/bukhari:3435", "t": "Testifying that He is alone, without partner", "k": "مَنْ شَهِدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "a": "kalima-tawheed.html#h-bukhari-3435"}, "Q:41:34": {"l": "Surah Fussilat, 41:34", "u": "https://quran.com/41/34", "ar": "وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ ﴿٣٤﴾", "tr": "And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend. (34)", "a": "ihsan.html#q-41-34"}, "Q:81:29": {"l": "Surah At-Takwir, 81:29", "u": "https://quran.com/81/29", "ar": "وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ ﴿٢٩﴾", "tr": "And you do not will except that Allah wills - Lord of the worlds. (29)", "a": "taqdeer.html#q-81-29"}};
window.DIAGRAMS={"t1": {"type": "flow", "title": "The purpose of creation at a glance", "hint": "Click any box (or select with Tab and press Enter) to see its evidence.", "nodes": [{"label": "Creation", "sub": "Jinn and mankind created", "desc": "Allah created the jinn and mankind, and made man hearing and seeing.", "refs": [["Q:51:56", ""], ["Q:76:2", ""]]}, {"label": "Purpose: Worship", "sub": "Servitude to Allah alone", "desc": "The purpose of creation is the worship of Allah alone, and Allah's right over His servants is that they worship Him and associate nothing with Him.", "refs": [["Q:51:56", ""], ["H:bukhari:2856", "أَنْ يَعْبُدُوهُ وَلاَ يُشْرِكُوا بِهِ شَيْئًا"]]}, {"label": "Condition: Sincerity", "sub": "Religion purely for Allah", "desc": "Worship fulfils its purpose only when it is purely for Allah; deeds depend on intentions.", "refs": [["Q:98:5", ""], ["Q:6:162", ""], ["H:bukhari:1", "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ"]]}, {"label": "Arena: The Test", "sub": "Who is best in deeds", "desc": "Life and death are for a test, and worship is to continue until the last breath.", "refs": [["Q:67:2", ""], ["Q:15:99", ""]]}, {"label": "End: The Return", "sub": "Accountability", "desc": "Man was not created without purpose; he must return to Allah, and the end of turning away from the purpose (shirk) is dreadful.", "refs": [["Q:23:115", ""], ["H:bukhari:6557", "أَنْ لاَ تُشْرِكَ بِي شَيْئًا"]]}]}, "t2": {"type": "kalima", "title": "The kalimah of tawhid: negation and affirmation", "hint": "Click both parts of the kalimah, then choose any of the requirements below.", "neg": {"label": "لَا إِلٰهَ", "sub": "Negation: no god", "desc": "The first part of the kalimah is the negation and rejection of every object of worship besides Allah.", "items": ["Taghut, which must be rejected", "Whatever is worshipped besides Allah", "What you worship (Ibrahim's declaration)", "What is called upon besides Allah: it is falsehood"], "refs": [["Q:2:256", ""], ["H:muslim:23", "وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ"], ["Q:43:26", ""], ["Q:22:62", ""]]}, "aff": {"label": "إِلَّا اللّٰهُ", "sub": "Affirmation: except Allah", "desc": "The second part affirms worship for Allah alone: belief in Allah, worship of Him, He is the Truth.", "refs": [["Q:2:256", ""], ["Q:43:27", ""], ["Q:16:51", ""], ["Q:47:19", ""]]}, "chips": [{"label": "Knowledge", "desc": "Knowing the meaning of the kalimah.", "refs": [["Q:47:19", ""], ["H:muslim:26", "مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ"]]}, {"label": "Certainty", "desc": "No doubt in the heart.", "refs": [["Q:49:15", ""], ["H:muslim:27", "لاَ يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فِيهِمَا إِلاَّ دَخَلَ الْجَنَّةَ"]]}, {"label": "Sincerity", "desc": "Religion and worship purely for Allah.", "refs": [["Q:39:3", ""], ["H:bukhari:99", "خَالِصًا مِنْ قَلْبِهِ"]]}, {"label": "Truthfulness", "desc": "Testifying with a truthful heart, not with the tongue alone.", "refs": [["H:bukhari:128", "صِدْقًا مِنْ قَلْبِهِ"]]}, {"label": "Love", "desc": "The believers love Allah more than anything else.", "refs": [["Q:2:165", ""]]}, {"label": "Rejecting all else", "desc": "Rejecting every object of worship besides Allah.", "refs": [["Q:2:256", ""], ["H:muslim:23", "وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ"]]}, {"label": "Acceptance (no arrogance)", "desc": "Being arrogant on hearing the kalimah is a trait of the deniers.", "refs": [["Q:37:35", ""]]}]}, "t3": {"type": "tree", "title": "The tree of belief in Allah", "hint": "Click the root or any branch to see the verses and hadith for that aspect.", "root": {"label": "Belief in Allah", "desc": "In the Hadith of Jibril, the first part of faith is belief in Allah.", "refs": [["H:muslim:8", "أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ"]]}, "nodes": [{"label": "Existence", "sub": "Allah exists", "desc": "Every creation has a Creator; there is no room for doubt about the Creator of the heavens and the earth.", "refs": [["Q:52:35-36", ""], ["Q:14:10", ""]]}, {"label": "Lordship", "sub": "Creator, Owner, Disposer", "desc": "Allah alone is Lord of the worlds, Creator and Guardian of all things; creation and command are His.", "refs": [["Q:1:2", ""], ["Q:39:62", ""], ["Q:7:54", ""], ["H:muslim:2713", "اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ"]]}, {"label": "Worship", "sub": "Worship is His alone", "desc": "There is only one God; acknowledging His lordship requires worshipping Him; the greatest sin is shirk.", "refs": [["Q:2:163", ""], ["Q:20:14", ""], ["Q:2:22", ""], ["H:bukhari:4477", "أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ"]]}, {"label": "Names & Attributes", "sub": "Beautiful names", "desc": "There is nothing like Him and He is the Hearing, the Seeing; His are the beautiful names, so call on Him by them.", "refs": [["Q:42:11", ""], ["Q:7:180", ""], ["Q:112:1-4", ""], ["H:bukhari:2736", "إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا"], ["H:bukhari:7375", "أَخْبِرُوهُ أَنَّ اللَّهَ يُحِبُّهُ"]]}]}, "t4": {"type": "wheel", "title": "The four aspects of decree", "hint": "Click any part of the circle or the centre.", "center": {"label": "Decree", "sub": "good and bad", "desc": "Belief in the decree, its good and its bad, is a pillar of faith.", "refs": [["H:muslim:8", "وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ"]]}, "nodes": [{"label": "Knowledge", "sub": "Allah knows all", "desc": "The keys of the unseen are with Him; everything in the heavens and the earth is within His knowledge.", "refs": [["Q:6:59", ""], ["Q:22:70", ""]]}, {"label": "Writing", "sub": "All is written", "desc": "The decrees were written fifty thousand years before the creation of the heavens and the earth; every disaster is in a Book beforehand.", "refs": [["Q:57:22", ""], ["H:muslim:2653b", "كَتَبَ اللَّهُ مَقَادِيرَ الْخَلاَئِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ"], ["H:bukhari:3191", "وَكَتَبَ فِي الذِّكْرِ كُلَّ شَىْءٍ"]]}, {"label": "Will", "sub": "What He wills happens", "desc": "The servant wills, but his willing is subject to the will of Allah, Lord of the worlds.", "refs": [["Q:81:29", ""], ["Q:76:30", ""], ["H:muslim:2664", "قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ"]]}, {"label": "Creation", "sub": "He creates all", "desc": "Allah created you and your deeds, and created everything with measure.", "refs": [["Q:37:96", ""], ["Q:54:49", ""], ["Q:25:2", ""]]}]}, "t5": {"type": "pyramid", "title": "The Hadith of Jibril: three levels of the religion", "hint": "Click any level of the pyramid. The order follows the order of the questions in the hadith.", "nodes": [{"label": "Islam", "sub": "Outward pillars", "desc": "The testimony of faith, prayer, zakah, fasting in Ramadan, and Hajj if one is able.", "refs": [["H:muslim:8", "الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ"], ["H:bukhari:8", "بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ"]]}, {"label": "Iman", "sub": "Beliefs of the heart", "desc": "Belief in Allah, the angels, the books, the messengers, the Last Day, and the decree, good and bad.", "refs": [["H:muslim:8", "أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ"], ["H:bukhari:50", "الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ"]]}, {"label": "Ihsan", "sub": "As though you see Him", "desc": "Worship Allah as though you see Him; and if not, then He sees you.", "refs": [["H:muslim:8", "أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ"], ["Q:26:218", ""]]}], "foot": {"label": "\"It was Jibril\"", "desc": "The Prophet ﷺ said it was Jibril who came to teach you your religion, that is, the three levels together are the religion.", "refs": [["H:muslim:8", "فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ"]]}, "chips": [{"label": "Parents", "desc": "Ihsan to parents alongside the worship of Allah; the mother is most deserving of good companionship.", "refs": [["Q:4:36", ""], ["H:bukhari:5971", ""]]}, {"label": "Neighbour & guest", "desc": "A requirement of faith: do not harm your neighbour, honour your guest.", "refs": [["H:bukhari:6018", "فَلاَ يُؤْذِ جَارَهُ"]]}, {"label": "The tongue", "desc": "Speak good or remain silent.", "refs": [["H:muslim:47", "فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ"]]}, {"label": "Brother", "desc": "Love for your brother what you love for yourself.", "refs": [["H:bukhari:13", "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ"]]}, {"label": "All people", "desc": "Whoever is not merciful to people, Allah is not merciful to him; forgiving increases honour.", "refs": [["H:bukhari:7376", "لاَ يَرْحَمُ اللَّهُ مَنْ لاَ يَرْحَمُ النَّاسَ"], ["H:muslim:2588", "وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا"]]}, {"label": "Animals", "desc": "Ihsan even in slaughter: sharpen the blade and give the animal ease.", "refs": [["H:muslim:1955", "إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَىْءٍ"]]}, {"label": "Enemies", "desc": "Repel evil in the best way.", "refs": [["Q:41:34", ""]]}]}};
window.QUIZ={"t1": [{"id": "t1-1", "q": "For what purpose did Allah create jinn and mankind?", "o": ["So that they worship Allah", "Only to populate the earth", "To provide sustenance to Allah", "Only to earn the world"], "e": "«وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ»", "r": "Q:51:56"}, {"id": "t1-2", "q": "According to Surat adh-Dhariyat, does Allah want provision or food from His servants?", "o": ["No, He Himself is the Provider, the Possessor of strength", "Yes, only provision", "Yes, only food", "The Quran does not mention it"], "e": "«مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ… إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ»", "r": "Q:51:57-58"}, {"id": "t1-3", "q": "What did the Prophet ﷺ tell Mu'adh was Allah's right over His servants?", "o": ["That they worship Him and associate nothing with Him", "Only that they fast Ramadan", "Only that they give charity", "Only that they perform Hajj"], "e": "In the hadith of Sahih al-Bukhari: «أَنْ يَعْبُدُوهُ وَلاَ يُشْرِكُوا بِهِ شَيْئًا»", "r": "H:bukhari:2856"}, {"id": "t1-4", "q": "In the same hadith, what is stated as the servants' right over Allah?", "o": ["That He not punish whoever does not associate partners with Him", "That every prayer be answered at once", "That everyone becomes wealthy", "That no trial ever comes"], "e": "«أَنْ لاَ يُعَذِّبَ مَنْ لاَ يُشْرِكُ بِهِ شَيْئًا»", "r": "H:bukhari:2856"}, {"id": "t1-5", "q": "When Mu'adh asked permission to give people this good news, what did the Prophet ﷺ say?", "o": ["Do not tell them, lest they rely on it (alone)", "Tell everyone immediately", "Tell only the scholars", "Tell them only on Friday"], "e": "«لاَ تُبَشِّرْهُمْ فَيَتَّكِلُوا»", "r": "H:bukhari:2856"}, {"id": "t1-6", "q": "According to Surat an-Nahl, what was the call of the messenger sent to every nation?", "o": ["Worship Allah and avoid taghut", "Only adopt good manners", "Only honesty in trade", "Only follow your forefathers"], "e": "«أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ»", "r": "Q:16:36"}, {"id": "t1-7", "q": "Which revelation to every messenger is mentioned in al-Anbiya' 21:25?", "o": ["There is no god except Me, so worship Me", "Only reform the world", "Let every nation choose its own god", "Only offer sacrifices"], "e": "«أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ»", "r": "Q:21:25"}, {"id": "t1-8", "q": "According to Surat al-Mulk, why were death and life created?", "o": ["To test who is best in deeds", "So that man may only rest", "So that time passes", "No reason is given"], "e": "«لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا»", "r": "Q:67:2"}, {"id": "t1-9", "q": "Which assumption is refuted in al-Mu'minun 23:115?", "o": ["That We created you without purpose and you will not be returned", "That the earth is round", "That the messengers are human", "That prayer is obligatory"], "e": "«أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا…»", "r": "Q:23:115"}, {"id": "t1-10", "q": "According to al-Bayyinah 98:5, how were people commanded to worship?", "o": ["Making the religion sincerely for Allah", "However they like", "Only for show", "Only occasionally"], "e": "«مُخْلِصِينَ لَهُ ٱلدِّينَ»", "r": "Q:98:5"}, {"id": "t1-11", "q": "In al-An'am 6:162, which things are declared to be for Allah, Lord of the worlds?", "o": ["Prayer, worship, living and dying", "Only prayer", "Only wealth", "Only fasting"], "e": "«إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ»", "r": "Q:6:162"}, {"id": "t1-12", "q": "According to al-Hijr 15:99, until when is worship to continue?", "o": ["Until death comes", "Until the age of forty", "Only in youth", "As long as one feels like it"], "e": "«وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ»", "r": "Q:15:99"}, {"id": "t1-13", "q": "According to the hadith, upon what is every child born?", "o": ["Upon the fitrah", "A blank mind with no religion", "Upon the religion of his parents", "Upon doubt"], "e": "«كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ»", "r": "H:bukhari:1385"}, {"id": "t1-14", "q": "What acknowledgement was taken from the children of Adam in al-A'raf 7:172?", "o": ["Am I not your Lord? They all said: Yes indeed", "Are you angels?", "Is the earth yours?", "Will you live forever?"], "e": "«أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ»", "r": "Q:7:172"}, {"id": "t1-15", "q": "According to the hadith qudsi, what is the most beloved thing by which a servant draws near to Allah?", "o": ["What Allah has made obligatory upon him", "Only voluntary deeds", "Only supplication", "Only travel"], "e": "«وَمَا تَقَرَّبَ إِلَىَّ عَبْدِي بِشَىْءٍ أَحَبَّ إِلَىَّ مِمَّا افْتَرَضْتُ عَلَيْهِ»", "r": "H:bukhari:6502"}, {"id": "t1-16", "q": "What is the example of one who remembers his Lord and one who does not?", "o": ["The living and the dead", "The rich and the poor", "Day and night", "The learned and the ignorant"], "e": "«مَثَلُ الْحَىِّ وَالْمَيِّتِ»", "r": "H:bukhari:6407"}, {"id": "t1-17", "q": "Which two blessings are most people at a loss in?", "o": ["Health and free time", "Wealth and children", "Knowledge and age", "House and mount"], "e": "«الصِّحَّةُ وَالْفَرَاغُ»", "r": "H:bukhari:6412"}, {"id": "t1-18", "q": "According to the hadith qudsi \"O My servants\", if all mankind and jinn became like the most pious heart, then?", "o": ["It would add nothing to Allah's dominion", "Allah's dominion would double", "Allah's need would be fulfilled", "The Hour would come"], "e": "«مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا»", "r": "H:muslim:2577"}, {"id": "t1-19", "q": "On the Day of Resurrection, what easy thing will Allah tell the person with the lightest punishment in Hell that He had asked of him?", "o": ["That you not associate anything with Me", "That you give the whole world as ransom", "That you fast every day", "That you never sleep"], "e": "«أَنْ لاَ تُشْرِكَ بِي شَيْئًا»", "r": "H:bukhari:6557"}, {"id": "t1-20", "q": "What is the subject of the first hadith of Sahih al-Bukhari?", "o": ["Deeds are judged by intentions", "Signs of the Hour", "The method of wudu", "The rites of Hajj"], "e": "«إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ»", "r": "H:bukhari:1"}], "t2": [{"id": "t2-1", "q": "What is commanded about the kalimah of tawhid in Muhammad 47:19?", "o": ["Know that there is no god except Allah", "Just say it with the tongue", "Recite it once a year", "It is not mentioned"], "e": "«فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ»", "r": "Q:47:19"}, {"id": "t2-2", "q": "According to Al 'Imran 3:18, who bore witness to «La ilaha illa huwa»?", "o": ["Allah, the angels and those of knowledge", "Only the prophets", "Only the jinn", "Only kings"], "e": "«شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ»", "r": "Q:3:18"}, {"id": "t2-3", "q": "What does the part «لَا إِلٰهَ» of the kalimah represent?", "o": ["Negation: rejecting every object of worship", "Affirmation: acknowledging Allah", "Only a supplication", "Only remembrance"], "e": "The same point comes in al-Baqarah 2:256 in the words «يَكْفُرْ بِٱلطَّٰغُوتِ» (rejecting taghut).", "r": "Q:2:256"}, {"id": "t2-4", "q": "What does the part «إِلَّا اللّٰهُ» of the kalimah represent?", "o": ["Affirmation: worship for Allah alone", "Negation: denying Allah", "Only an exception with no meaning", "Acknowledging the angels"], "e": "In al-Baqarah 2:256, «وَيُؤْمِنۢ بِٱللَّهِ» (believing in Allah) expresses this affirmation.", "r": "Q:2:256"}, {"id": "t2-5", "q": "According to al-Baqarah 2:256, who has grasped the \"firmest handhold\"?", "o": ["Whoever rejects taghut and believes in Allah", "Whoever only claims belief in Allah", "Whoever only rejects taghut", "Whoever does nothing"], "e": "«فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ»", "r": "Q:2:256"}, {"id": "t2-6", "q": "According to Sahih Muslim 23, what is mentioned alongside saying La ilaha illallah for the protection of life and property?", "o": ["Rejecting whatever is worshipped besides Allah", "Only prayer", "Only fasting", "Nothing at all"], "e": "«مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ…»", "r": "H:muslim:23"}, {"id": "t2-7", "q": "After «إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ», whom did Ibrahim (peace be upon him) make an exception?", "o": ["The One who created me", "His father", "One of his people's idols", "No one"], "e": "«إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ»", "r": "Q:43:26-27"}, {"id": "t2-8", "q": "According to az-Zukhruf 43:28, what did Ibrahim (peace be upon him) make of this statement?", "o": ["A word remaining among his descendants", "Only a personal opinion", "A story", "A poem"], "e": "«وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةًۭ فِى عَقِبِهِۦ»", "r": "Q:43:28"}, {"id": "t2-9", "q": "According to al-Hajj 22:62, what are those called upon besides Allah?", "o": ["Falsehood", "The truth", "Equal partners", "Intercessors whose worship is permitted"], "e": "«وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ»", "r": "Q:22:62"}, {"id": "t2-10", "q": "Which proof is given in al-Anbiya' 21:22?", "o": ["If there were gods besides Allah, the heavens and earth would have been ruined", "The more gods, the better", "The earth has a separate god", "There is no proof in this verse"], "e": "«لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا»", "r": "Q:21:22"}, {"id": "t2-11", "q": "According to Sahih Muslim 26, who will enter Paradise?", "o": ["Whoever dies knowing that there is no god but Allah", "Whoever was merely born in a Muslim home", "Whoever prayed once", "Whoever heard the kalimah"], "e": "«مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ»", "r": "H:muslim:26"}, {"id": "t2-12", "q": "In Sahih Muslim 27, what condition is stated for one who meets Allah with the two testimonies?", "o": ["That he has no doubt about them", "That he is rich", "That he is a scholar", "That he is an Arab"], "e": "«لاَ يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فِيهِمَا إِلاَّ دَخَلَ الْجَنَّةَ»", "r": "H:muslim:27"}, {"id": "t2-13", "q": "Who will be the most fortunate with the Prophet's ﷺ intercession on the Day of Resurrection?", "o": ["Whoever said La ilaha illallah purely from his heart", "Whoever spent the most wealth", "Whoever was born first", "Whoever was the strongest"], "e": "«مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ خَالِصًا مِنْ قَلْبِهِ أَوْ نَفْسِهِ»", "r": "H:bukhari:99"}, {"id": "t2-14", "q": "In Sahih al-Bukhari 128, how is the testimony to be given?", "o": ["Truthfully from the heart (صِدْقًا مِنْ قَلْبِهِ)", "Only loudly", "Only in writing", "Only in a congregation"], "e": "«…صِدْقًا مِنْ قَلْبِهِ إِلاَّ حَرَّمَهُ اللَّهُ عَلَى النَّارِ»", "r": "H:bukhari:128"}, {"id": "t2-15", "q": "According to al-Hujurat 49:15, what is a quality of the true believers?", "o": ["They do not doubt after believing", "They never ask questions", "They only make claims", "They only acquire knowledge"], "e": "«ثُمَّ لَمْ يَرْتَابُوا۟»", "r": "Q:49:15"}, {"id": "t2-16", "q": "According to al-Baqarah 2:165, how is the believers' love for Allah?", "o": ["Stronger than anything else", "Equal to others", "Little", "Conditional"], "e": "«وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّۭا لِّلَّهِ»", "r": "Q:2:165"}, {"id": "t2-17", "q": "According to as-Saffat 37:35, what did the deniers do when told «La ilaha illallah»?", "o": ["They were arrogant", "They accepted at once", "They stayed silent", "They began to weep"], "e": "«إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ»", "r": "Q:37:35"}, {"id": "t2-18", "q": "What is the highest branch of faith?", "o": ["Saying La ilaha illallah", "Removing something harmful from the road", "Modesty", "Giving salam"], "e": "«فَأَفْضَلُهَا قَوْلُ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ»", "r": "H:muslim:35b"}, {"id": "t2-19", "q": "What is the first of the five things upon which Islam is built?", "o": ["Testifying La ilaha illallah and that Muhammad is the Messenger of Allah", "Hajj", "Fasting", "Zakah"], "e": "«بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ…»", "r": "H:bukhari:8"}, {"id": "t2-20", "q": "According to Sahih al-Bukhari 44, how much good in the heart of one who said the kalimah will still bring him out of Hell?", "o": ["An atom's weight", "A mountain's weight", "Only half a heart", "None at all"], "e": "«وَفِي قَلْبِهِ وَزْنُ ذَرَّةٍ مِنْ خَيْرٍ»", "r": "H:bukhari:44"}, {"id": "t2-21", "q": "What did Allah command in an-Nahl 16:51?", "o": ["Do not take two gods; He is only one God", "You may take two gods", "Every nation has a separate god", "There is no mention of god"], "e": "«لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ»", "r": "Q:16:51"}], "t3": [{"id": "t3-1", "q": "Which question is raised in at-Tur 52:35?", "o": ["Were they created by nothing, or are they the creators?", "Is the sun bigger than the moon?", "Is the earth stationary?", "Can jinn be seen?"], "e": "«أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ»", "r": "Q:52:35"}, {"id": "t3-2", "q": "What did the messengers say to their peoples about Allah (Ibrahim 14:10)?", "o": ["Is there any doubt about Allah, Creator of the heavens and the earth?", "Someone created Allah", "Do not believe in Allah without seeing Him", "Only we have knowledge of Allah"], "e": "«أَفِى ٱللَّهِ شَكٌّۭ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ»", "r": "Q:14:10"}, {"id": "t3-3", "q": "In which verse of Surat al-Fatihah is \"Lord of the worlds\" mentioned?", "o": ["Verse 2", "Verse 5", "Verse 7", "Verse 4"], "e": "«ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ» (al-Fatihah 1:2)", "r": "Q:1:2"}, {"id": "t3-4", "q": "What is the meaning of «أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ» in al-A'raf 7:54?", "o": ["Creating and commanding belong to Him", "Only creating belongs to Him", "Commanding belongs to humans only", "It is about the angels"], "e": "Lordship: both creation and command belong to Allah", "r": "Q:7:54"}, {"id": "t3-5", "q": "According to az-Zumar 39:62, what is Allah?", "o": ["Creator of all things and Guardian over all things", "Creator of the heavens only", "Creator of humans only", "Only a helper"], "e": "«ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ»", "r": "Q:39:62"}, {"id": "t3-6", "q": "According to Yunus 10:31, when the polytheists were asked about provision, hearing and sight, and the arranging of affairs, what did they answer?", "o": ["Allah", "Our idols", "No one", "We ourselves"], "e": "«فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ»", "r": "Q:10:31"}, {"id": "t3-7", "q": "What lesson do we learn from al-Mu'minun 23:84-89?", "o": ["Accepting Allah as Creator and Owner requires fearing Him and worshipping Him alone", "Merely accepting is enough", "The polytheists did not know Allah", "These verses are about decree"], "e": "After every answer \"Allah\" comes a question: «أَفَلَا تَذَكَّرُونَ… أَفَلَا تَتَّقُونَ… فَأَنَّىٰ تُسْحَرُونَ»", "r": "Q:23:84-89"}, {"id": "t3-8", "q": "In al-Baqarah 2:22, what was commanded after listing the signs of lordship?", "o": ["Do not knowingly set up rivals to Allah", "Worship the sky", "Stop praying for rain", "Make the earth a god"], "e": "«فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًۭا وَأَنتُمْ تَعْلَمُونَ»", "r": "Q:2:22"}, {"id": "t3-9", "q": "Which sin is the greatest according to the Prophet ﷺ?", "o": ["Setting up a rival to Allah while He created you", "Lying", "Theft", "Backbiting"], "e": "«أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ»", "r": "H:bukhari:4477"}, {"id": "t3-10", "q": "What did Allah say to Musa (peace be upon him) in Ta-Ha 20:14?", "o": ["Indeed I am Allah; there is no god but Me, so worship Me and establish prayer for My remembrance", "Obey Pharaoh", "Go to the mountain", "Only fast"], "e": "«إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ»", "r": "Q:20:14"}, {"id": "t3-11", "q": "Which two matters are in the verse «لَيْسَ كَمِثْلِهِۦ شَىْءٌ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ» of ash-Shura 42:11?", "o": ["Negating resemblance and affirming hearing and seeing", "Only denying the attributes", "Only praising creation", "Mention of the angels"], "e": "The first part negates being like creation; the second part affirms the attributes of hearing and seeing.", "r": "Q:42:11"}, {"id": "t3-12", "q": "According to al-A'raf 7:180, how is Allah to be called upon?", "o": ["By His beautiful names", "By any invented name", "Only by gestures", "He is not to be called upon"], "e": "«وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا»", "r": "Q:7:180"}, {"id": "t3-13", "q": "According to the hadith, how many names does Allah have that whoever preserves them will enter Paradise?", "o": ["Ninety-nine (one less than a hundred)", "One hundred", "Seventy", "Thirty"], "e": "«إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً إِلاَّ وَاحِدًا»", "r": "H:bukhari:2736"}, {"id": "t3-14", "q": "The Companion who ended every recitation with «Qul huwa Allahu ahad», what reason did he give?", "o": ["It is the description of ar-Rahman and I love to recite it", "It is the shortest surah", "He knew no other surah", "It was an order"], "e": "«لأَنَّهَا صِفَةُ الرَّحْمَنِ وَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا», and the Prophet ﷺ said: Allah loves him.", "r": "H:bukhari:7375"}, {"id": "t3-15", "q": "According to Sahih Muslim 179, what was said about Allah?", "o": ["He does not sleep, and sleep does not befit Him", "He sometimes sleeps", "He is awake only by day", "It is not mentioned"], "e": "«إِنَّ اللَّهَ عَزَّ وَجَلَّ لاَ يَنَامُ وَلاَ يَنْبَغِي لَهُ أَنْ يَنَامَ»", "r": "H:muslim:179"}, {"id": "t3-16", "q": "What did the Prophet ﷺ say to those saying takbir loudly on a journey?", "o": ["You are not calling one deaf or absent, but One who hears and sees", "Call out even louder", "Be silent and never remember Him", "Only say His name in your heart"], "e": "«فَإِنَّكُمْ لاَ تَدْعُونَ أَصَمَّ وَلاَ غَائِبًا وَلَكِنْ تَدْعُونَ سَمِيعًا بَصِيرًا»", "r": "H:bukhari:6384"}, {"id": "t3-17", "q": "According to the hadith, when does Allah descend to the lowest heaven every night?", "o": ["When the last third of the night remains", "At sunset", "Before midnight", "Only on Friday night"], "e": "«حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ»", "r": "H:bukhari:1145"}, {"id": "t3-18", "q": "What did Allah write in His Book after creating the creation?", "o": ["My mercy prevails over My anger", "My anger prevails over My mercy", "All are equal", "He wrote nothing"], "e": "«إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي»", "r": "H:bukhari:3194"}, {"id": "t3-19", "q": "Into how many parts did Allah make mercy, and how many did He send down to earth?", "o": ["One hundred parts, one to the earth", "Ten parts, five to the earth", "One hundred parts, fifty to the earth", "One part, that same one to the earth"], "e": "«جَعَلَ اللَّهُ الرَّحْمَةَ مِائَةَ جُزْءٍ… وَأَنْزَلَ فِي الأَرْضِ جُزْءًا وَاحِدًا»", "r": "H:bukhari:6000"}, {"id": "t3-20", "q": "In the supplication of Sahih Muslim 2713, what is said in calling Allah \"the First\"?", "o": ["There is nothing before You", "There is no one after You", "There is no one above You", "Everything is beneath You"], "e": "«اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَىْءٌ»", "r": "H:muslim:2713"}], "t4": [{"id": "t4-1", "q": "In the Hadith of Jibril, what is the last of the pillars of faith?", "o": ["Belief in the decree, its good and its bad", "The Last Day", "The books", "The angels"], "e": "«وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ»", "r": "H:muslim:8"}, {"id": "t4-2", "q": "According to Ibn 'Umar, if a denier of the decree spent gold equal to Uhud, then?", "o": ["Allah would not accept it until he believes in the decree", "It would be accepted", "Half would be accepted", "It is not mentioned"], "e": "«مَا قَبِلَ اللَّهُ مِنْهُ حَتَّى يُؤْمِنَ بِالْقَدَرِ»", "r": "H:muslim:8"}, {"id": "t4-3", "q": "What does al-Qamar 54:49 tell us?", "o": ["We created everything with measure", "Everything happened by chance", "Some things have no creator", "Decree is for humans only"], "e": "«إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍۢ»", "r": "Q:54:49"}, {"id": "t4-4", "q": "According to Sahih Muslim, what is the ruling on \"incapacity and ability\" with respect to the decree?", "o": ["They too are by decree", "They are outside the decree", "Only ability is by decree", "It is not mentioned"], "e": "«كُلُّ شَىْءٍ بِقَدَرٍ حَتَّى الْعَجْزُ وَالْكَيْسُ»", "r": "H:muslim:2656"}, {"id": "t4-5", "q": "With whom are the keys of the unseen (al-An'am 6:59)?", "o": ["With Allah alone", "With the angels", "With astrologers", "With the jinn"], "e": "«وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ»", "r": "Q:6:59"}, {"id": "t4-6", "q": "According to al-An'am 6:59, which thing is not outside Allah's knowledge?", "o": ["Every leaf that falls", "Only major events", "Only human actions", "Only things in the sky"], "e": "«وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا»", "r": "Q:6:59"}, {"id": "t4-7", "q": "Which two aspects of decree come together in al-Hajj 22:70?", "o": ["Knowledge and being written in a Book", "Will and creation", "Only creation", "Only will"], "e": "«أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ»", "r": "Q:22:70"}, {"id": "t4-8", "q": "When did Allah write the decrees of the creatures?", "o": ["Fifty thousand years before creating the heavens and the earth", "After the birth of man", "On the Day of Resurrection", "Anew every year"], "e": "«كَتَبَ اللَّهُ مَقَادِيرَ الْخَلاَئِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ»", "r": "H:muslim:2653b"}, {"id": "t4-9", "q": "According to the same hadith, where was Allah's Throne at that time?", "o": ["Upon the water", "Upon the earth", "Upon a mountain", "It is not mentioned"], "e": "«وَعَرْشُهُ عَلَى الْمَاءِ»", "r": "H:muslim:2653b"}, {"id": "t4-10", "q": "According to al-Hadid 57:22, a disaster striking the earth or yourselves:", "o": ["is written in a Book before it is brought into being", "comes suddenly without knowledge", "comes only to disbelievers", "is not written"], "e": "«إِلَّا فِى كِتَٰبٍۢ مِّن قَبْلِ أَن نَّبْرَأَهَآ»", "r": "Q:57:22"}, {"id": "t4-11", "q": "What wisdom is given in al-Hadid 57:23 for hardships being written beforehand?", "o": ["Do not grieve over what you missed nor exult over what you were given", "So that you abandon deeds", "So that you stay afraid and do nothing", "There is no wisdom"], "e": "«لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ»", "r": "Q:57:23"}, {"id": "t4-12", "q": "Which four things does the angel write in the mother's womb?", "o": ["Deeds, provision, life-span, and whether wretched or blessed", "Name, colour, height, language", "City, house, profession, friends", "Only the life-span"], "e": "«اكْتُبْ عَمَلَهُ وَرِزْقَهُ وَأَجَلَهُ وَشَقِيٌّ أَوْ سَعِيدٌ»", "r": "H:bukhari:3208"}, {"id": "t4-13", "q": "According to at-Takwir 81:29, the servant's willing is subject to what?", "o": ["The will of Allah, Lord of the worlds", "Only his own wish", "The wish of the angels", "Nothing"], "e": "«وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ»", "r": "Q:81:29"}, {"id": "t4-14", "q": "What did Ibrahim (peace be upon him) say in as-Saffat 37:96?", "o": ["It is Allah who created you and what you do/make", "The idols made themselves", "Man is his own creator", "This verse is not about worship"], "e": "«وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ»", "r": "Q:37:96"}, {"id": "t4-15", "q": "When the Companions asked whether they should rely on what is written and give up deeds, what did the Prophet ﷺ say?", "o": ["Do deeds; each is facilitated for what he was created for", "Yes, give up deeds", "Only make supplication", "He did not answer"], "e": "«اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ»", "r": "H:bukhari:4949"}, {"id": "t4-16", "q": "According to Sahih Muslim 2664, what should not be said when a loss occurs?", "o": ["\"If only I had done such-and-such, it would have been so\"", "«Qadar Allah wa ma sha'a fa'al»", "«Alhamdulillah»", "«Inna lillah»"], "e": "«فَلاَ تَقُلْ لَوْ أَنِّي فَعَلْتُ… وَلَكِنْ قُلْ قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ»", "r": "H:muslim:2664"}, {"id": "t4-17", "q": "Why is the affair of the believer amazing (Sahih Muslim 2999)?", "o": ["Gratitude in joy and patience in hardship, both are good for him", "He never faces hardship", "He always has joy", "He is never grateful"], "e": "«إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ»", "r": "H:muslim:2999"}, {"id": "t4-18", "q": "According to at-Taghabun 64:11, what does one who believes in Allah receive?", "o": ["Allah guides his heart", "No disaster ever comes", "His wealth increases", "Nothing"], "e": "«وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ»", "r": "Q:64:11"}, {"id": "t4-19", "q": "Adam (peace be upon him) told Musa (peace be upon him) that the thing he was blamed for had been written when?", "o": ["Forty years before I was created", "After I was created", "After leaving Paradise", "It was never written"], "e": "«قَدَّرَ اللَّهُ عَلَىَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً»", "r": "H:bukhari:6614"}, {"id": "t4-20", "q": "In Sahih al-Bukhari 6616, from what are we commanded to seek refuge?", "o": ["The hardship of trial, the depth of misery, an evil decree, and the gloating of enemies", "Only poverty", "Only illness", "Only travel"], "e": "«تَعَوَّذُوا بِاللَّهِ مِنْ جَهْدِ الْبَلاَءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ»", "r": "H:bukhari:6616"}, {"id": "t4-21", "q": "What does the believer declare in at-Tawbah 9:51?", "o": ["Nothing will befall us except what Allah has written for us", "Nothing can befall us", "We write our own decree", "Decree is nothing"], "e": "«قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا»", "r": "Q:9:51"}], "t5": [{"id": "t5-1", "q": "What is the definition of ihsan in the Hadith of Jibril?", "o": ["Worship Allah as though you see Him; otherwise, He sees you", "Only doing favours to people", "Only giving charity", "Only praying voluntary prayers"], "e": "«أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ»", "r": "H:muslim:8"}, {"id": "t5-2", "q": "Which three levels are described in order in the Hadith of Jibril?", "o": ["Islam, Iman, Ihsan", "Iman, knowledge, action", "Repentance, asceticism, piety", "Prayer, fasting, Hajj"], "e": "The questioner asked, in order, about Islam, Iman and Ihsan.", "r": "H:muslim:8"}, {"id": "t5-3", "q": "At the end of the hadith, what did the Prophet ﷺ say about the questioner?", "o": ["It was Jibril, who came to teach you your religion", "He was a bedouin", "He was a merchant", "He ﷺ said nothing"], "e": "«فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ»", "r": "H:muslim:8"}, {"id": "t5-4", "q": "In the narration of Sahih Muslim, what did the questioner look like?", "o": ["Very white clothes, very black hair, no trace of travel", "Dusty travelling clothes", "Red clothes", "His appearance is not mentioned"], "e": "«شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ الشَّعَرِ لاَ يُرَى عَلَيْهِ أَثَرُ السَّفَرِ»", "r": "H:muslim:8"}, {"id": "t5-5", "q": "When asked about the time of the Hour, what did the Prophet ﷺ say?", "o": ["The one asked knows no more about it than the one asking", "It will come tomorrow", "After a hundred years", "I know but will not tell"], "e": "«مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ»", "r": "H:muslim:8"}, {"id": "t5-6", "q": "According to ash-Shu'ara' 26:218, when does Allah see the servant?", "o": ["When he stands (in prayer)", "Only at night", "Only in the mosque", "Never"], "e": "«ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ»", "r": "Q:26:218"}, {"id": "t5-7", "q": "What assurance is given in al-Hadid 57:4?", "o": ["He is with you wherever you are and sees what you do", "He only knows about the heavens", "He only sees major deeds", "He sees nothing"], "e": "«وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ»", "r": "Q:57:4"}, {"id": "t5-8", "q": "According to Qaf 50:16, how near is Allah to a human being?", "o": ["Closer than the jugular vein", "Very far", "Near only during worship", "Nearness is not mentioned"], "e": "«وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ»", "r": "Q:50:16"}, {"id": "t5-9", "q": "What does Allah command in an-Nahl 16:90?", "o": ["Justice, ihsan and giving to relatives", "Only justice", "Only jihad", "Only trade"], "e": "«إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ»", "r": "Q:16:90"}, {"id": "t5-10", "q": "According to al-Baqarah 2:195, whom does Allah love?", "o": ["The muhsinin (doers of good)", "Only the rich", "Only the powerful", "Everyone equally"], "e": "«وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ»", "r": "Q:2:195"}, {"id": "t5-11", "q": "Which people are called muhsinin in Al 'Imran 3:134?", "o": ["Those who spend in ease and hardship, restrain anger and pardon people", "Only those who pray", "Only the learned", "Only travellers"], "e": "«وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ»", "r": "Q:3:134"}, {"id": "t5-12", "q": "What does ar-Rahman 55:60 say?", "o": ["Is the reward for ihsan anything but ihsan?", "The reward for evil is evil", "Every deed is rewarded in this world", "There is no reward"], "e": "«هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ»", "r": "Q:55:60"}, {"id": "t5-13", "q": "According to Sahih Muslim 1955, upon what has Allah prescribed ihsan?", "o": ["Upon everything", "Only upon prayer", "Only upon trade", "Only upon parents"], "e": "«إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَىْءٍ»", "r": "H:muslim:1955"}, {"id": "t5-14", "q": "In the same hadith, what example of ihsan in slaughter is given?", "o": ["Sharpen your blade and give the animal ease", "Slaughter in a hurry", "Use a blunt knife", "No example is given"], "e": "«وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ فَلْيُرِحْ ذَبِيحَتَهُ»", "r": "H:muslim:1955"}, {"id": "t5-15", "q": "What does Allah look at (Sahih Muslim 2564)?", "o": ["Hearts and deeds", "Faces", "Wealth", "Lineage"], "e": "«وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ»", "r": "H:muslim:2564c"}, {"id": "t5-16", "q": "In an-Nisa' 4:36, what is commanded immediately after the command to worship Allah?", "o": ["Ihsan to parents", "Trade", "Travel", "Hunting"], "e": "«وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا»", "r": "Q:4:36"}, {"id": "t5-17", "q": "According to al-Isra' (Bani Isra'il) 17:23, what must not be said to aged parents?", "o": ["Not even \"uff\"", "Salam", "Thank you", "A prayer for them"], "e": "«فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا»", "r": "Q:17:23"}, {"id": "t5-18", "q": "Who is most deserving of good companionship?", "o": ["Your mother (three times), then your father", "Father, then mother", "Brother", "Friend"], "e": "The Prophet ﷺ said «أُمُّكَ» three times, then «أَبُوكَ».", "r": "H:bukhari:5971"}, {"id": "t5-19", "q": "According to Sahih al-Bukhari 13, what is a condition of complete faith?", "o": ["Love for your brother what you love for yourself", "Only worry about yourself", "Argue with everyone", "Meet no one"], "e": "«لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ»", "r": "H:bukhari:13"}, {"id": "t5-20", "q": "What is the command about the tongue for one who believes in Allah and the Last Day?", "o": ["Speak good or remain silent", "Say whatever he likes", "Always remain silent", "Only argue"], "e": "«فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ»", "r": "H:muslim:47"}, {"id": "t5-21", "q": "What example is given of the believers' mutual mercy and love?", "o": ["One body: when one limb aches, the whole body suffers", "A building with a crack", "Two rivers", "A caravan"], "e": "«كَمَثَلِ الْجَسَدِ إِذَا اشْتَكَى عُضْوًا تَدَاعَى لَهُ سَائِرُ جَسَدِهِ بِالسَّهَرِ وَالْحُمَّى»", "r": "H:bukhari:6011"}, {"id": "t5-22", "q": "According to Sahih al-Bukhari 7376, to whom is Allah not merciful?", "o": ["Whoever is not merciful to people", "Whoever is poor", "Whoever is ill", "Whoever is travelling"], "e": "«لاَ يَرْحَمُ اللَّهُ مَنْ لاَ يَرْحَمُ النَّاسَ»", "r": "H:bukhari:7376"}, {"id": "t5-23", "q": "According to Sahih Muslim 2588, what results from forgiving?", "o": ["Allah increases the servant in honour", "Honour decreases", "Wealth decreases", "Nothing happens"], "e": "«وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا»", "r": "H:muslim:2588"}, {"id": "t5-24", "q": "According to Fussilat 41:34, how is evil to be repelled?", "o": ["By that which is best", "With evil", "Never, only by silence", "With harshness"], "e": "«ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ»", "r": "Q:41:34"}]};
